import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from './AuthContext';

const WorkerDashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('overview');
  const [tasks, setTasks] = useState([
    { id: 1, title: 'Monitor Gate A', status: 'active', priority: 'high' },
    { id: 2, title: 'Queue Management', status: 'active', priority: 'high' },
    { id: 3, title: 'Health Check Round', status: 'pending', priority: 'medium' }
  ]);
  const [liveData, setLiveData] = useState({
    currentCrowd: 4250,
    entryRate: 85,
    exitRate: 45,
    tasksCompleted: 12,
    activeAlerts: 2
  });

  useEffect(() => {
    const interval = setInterval(() => {
      setLiveData(prev => ({
        currentCrowd: Math.max(3000, Math.min(6000, prev.currentCrowd + Math.floor((Math.random() - 0.5) * 100))),
        entryRate: Math.max(30, Math.min(150, prev.entryRate + Math.floor((Math.random() - 0.5) * 20))),
        exitRate: Math.max(20, Math.min(100, prev.exitRate + Math.floor((Math.random() - 0.5) * 15))),
        tasksCompleted: prev.tasksCompleted,
        activeAlerts: Math.max(0, Math.min(5, prev.activeAlerts + Math.floor((Math.random() - 0.8) * 1)))
      }));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  const handleLogout = () => {
    logout();
    navigate('/worker-signin');
  };

  const completeTask = (id) => {
    setTasks(tasks.map(task =>
      task.id === id ? { ...task, status: 'completed' } : task
    ));
    setLiveData(prev => ({ ...prev, tasksCompleted: prev.tasksCompleted + 1 }));
  };

  if (!user || user.role !== 'worker') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-purple-50 to-indigo-50 flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-purple-600 mb-4">Access Denied</h2>
          <p className="text-gray-600 mb-6">You must be logged in as a worker to access this page.</p>
          <button
            onClick={() => navigate('/worker-signin')}
            className="bg-purple-500 hover:bg-purple-600 text-white font-bold py-2 px-6 rounded-lg"
          >
            Go to Worker Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 via-white to-indigo-50">
      {/* Header */}
      <header className="bg-white shadow-md border-b-4 border-purple-500">
        <div className="max-w-7xl mx-auto px-6 py-6 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-xl flex items-center justify-center text-white text-xl">
              👷
            </div>
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Worker Dashboard</h1>
              <p className="text-sm text-gray-600">Welcome, {user.fullName}</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-right">
              <p className="text-sm font-semibold text-gray-900">{user.department}</p>
              <p className="text-xs text-gray-600">{user.templeCity}</p>
            </div>
            <button
              onClick={handleLogout}
              className="bg-red-500 hover:bg-red-600 text-white font-bold py-2 px-4 rounded-lg transition-all"
            >
              Sign Out
            </button>
          </div>
        </div>
      </header>

      {/* Navigation Tabs */}
      <nav className="bg-white border-b-2 border-gray-200 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-6 flex gap-8">
          {[
            { id: 'overview', label: '📊 Overview', icon: '📊' },
            { id: 'tasks', label: '✅ My Tasks', icon: '✅' },
            { id: 'zones', label: '📍 Zone Management', icon: '📍' },
            { id: 'alerts', label: '🚨 Alerts', icon: '🚨' },
            { id: 'reports', label: '📈 Reports', icon: '📈' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`py-4 px-2 font-semibold border-b-4 transition-all ${
                activeTab === tab.id
                  ? 'text-purple-600 border-purple-600'
                  : 'text-gray-600 border-transparent hover:text-gray-900'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-6 py-10">
        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <div className="space-y-8">
            {/* Critical Alerts */}
            {liveData.activeAlerts > 0 && (
              <div className="bg-gradient-to-r from-orange-500 to-red-600 text-white rounded-2xl p-6 shadow-lg">
                <h3 className="text-2xl font-bold mb-2">⚠️ {liveData.activeAlerts} Active Alert(s)</h3>
                <p className="text-sm">Check the Alerts section for more details</p>
              </div>
            )}

            {/* Live KPI Cards */}
            <div className="grid md:grid-cols-5 gap-4">
              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-blue-500">
                <p className="text-gray-600 text-sm font-semibold">👥 Current Crowd</p>
                <p className="text-3xl font-bold text-gray-900 mt-2">{liveData.currentCrowd.toLocaleString()}</p>
              </div>

              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-green-500">
                <p className="text-gray-600 text-sm font-semibold">📥 Entry Rate</p>
                <p className="text-3xl font-bold text-gray-900 mt-2">{liveData.entryRate}/min</p>
              </div>

              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-orange-500">
                <p className="text-gray-600 text-sm font-semibold">📤 Exit Rate</p>
                <p className="text-3xl font-bold text-gray-900 mt-2">{liveData.exitRate}/min</p>
              </div>

              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-purple-500">
                <p className="text-gray-600 text-sm font-semibold">✅ Tasks Completed</p>
                <p className="text-3xl font-bold text-purple-600 mt-2">{liveData.tasksCompleted}</p>
              </div>

              <div className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-red-500">
                <p className="text-gray-600 text-sm font-semibold">🚨 Active Alerts</p>
                <p className="text-3xl font-bold text-red-600 mt-2">{liveData.activeAlerts}</p>
              </div>
            </div>

            {/* Assigned Zone */}
            <div className="bg-white rounded-2xl shadow-lg p-8">
              <h3 className="text-2xl font-bold text-gray-900 mb-6">📍 Your Assigned Zone</h3>
              <div className="grid md:grid-cols-2 gap-8">
                <div className="border-2 border-purple-200 rounded-2xl p-6">
                  <p className="text-sm text-gray-600 mb-2">Zone</p>
                  <p className="text-3xl font-bold text-gray-900">Zone 1 - Entry Gate</p>
                  <p className="text-gray-600 mt-3 text-sm">Status: <span className="font-bold text-green-600">✅ Active</span></p>
                </div>
                <div className="space-y-3">
                  <div className="p-4 bg-purple-50 rounded-lg">
                    <p className="text-sm text-gray-600">Current Crowd Density</p>
                    <div className="flex items-center gap-2 mt-2">
                      <div className="flex-1 h-3 bg-gray-200 rounded-full overflow-hidden">
                        <div className="h-full bg-yellow-500" style={{width: '65%'}}></div>
                      </div>
                      <p className="font-bold text-gray-900">65%</p>
                    </div>
                  </div>
                  <button className="w-full bg-purple-500 hover:bg-purple-600 text-white font-bold py-3 rounded-lg transition-all">
                    📊 View Zone Details
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* My Tasks Tab */}
        {activeTab === 'tasks' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-900">✅ My Tasks</h2>
            <div className="space-y-4">
              {tasks.map(task => (
                <div key={task.id} className="bg-white rounded-2xl shadow-lg p-6 border-l-4 border-purple-500">
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <h4 className="text-lg font-bold text-gray-900">{task.title}</h4>
                      <div className="flex gap-3 mt-2">
                        <span className={`text-xs px-3 py-1 rounded-full font-semibold ${
                          task.priority === 'high' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
                        }`}>
                          {task.priority.toUpperCase()} PRIORITY
                        </span>
                        <span className={`text-xs px-3 py-1 rounded-full font-semibold ${
                          task.status === 'completed' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'
                        }`}>
                          {task.status.toUpperCase()}
                        </span>
                      </div>
                    </div>
                    {task.status !== 'completed' && (
                      <button
                        onClick={() => completeTask(task.id)}
                        className="bg-green-500 hover:bg-green-600 text-white font-bold py-2 px-4 rounded-lg transition-all"
                      >
                        ✓ Mark Complete
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Zone Management Tab */}
        {activeTab === 'zones' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-900">📍 Zone Management</h2>
            <div className="grid md:grid-cols-2 gap-6">
              {['Entry Gate', 'Main Hall', 'Queue Area', 'Exit Gate'].map((zone, idx) => (
                <div key={idx} className="bg-white rounded-2xl shadow-lg p-6">
                  <h3 className="font-bold text-gray-900 mb-4">{zone}</h3>
                  <div className="space-y-3">
                    <div>
                      <p className="text-sm text-gray-600 mb-1">Crowd Level</p>
                      <div className="flex items-center gap-2">
                        <div className="flex-1 h-2 bg-gray-200 rounded-full overflow-hidden">
                          <div 
                            className={`h-full ${[70, 85, 50, 35][idx] > 75 ? 'bg-red-500' : [70, 85, 50, 35][idx] > 50 ? 'bg-yellow-500' : 'bg-green-500'}`} 
                            style={{width: `${[70, 85, 50, 35][idx]}%`}}
                          ></div>
                        </div>
                        <p className="font-bold text-gray-900">{[70, 85, 50, 35][idx]}%</p>
                      </div>
                    </div>
                    <button className="w-full bg-blue-500 hover:bg-blue-600 text-white py-2 px-4 rounded-lg font-semibold transition-all">
                      📊 Manage Zone
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Alerts Tab */}
        {activeTab === 'alerts' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-900">🚨 Active Alerts</h2>
            <div className="space-y-4">
              <div className="bg-red-50 border-l-4 border-red-500 rounded-2xl p-6">
                <div className="flex items-start gap-4">
                  <span className="text-3xl">🚨</span>
                  <div className="flex-1">
                    <h3 className="font-bold text-gray-900 text-lg">High Crowd Density Alert</h3>
                    <p className="text-gray-600 text-sm mt-1">Zone 2 (Main Hall) has reached 85% capacity. Please manage crowd flow.</p>
                    <div className="mt-3 flex gap-3">
                      <button className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg font-semibold text-sm">
                        ✓ Acknowledge
                      </button>
                      <button className="bg-gray-300 hover:bg-gray-400 text-gray-900 px-4 py-2 rounded-lg font-semibold text-sm">
                        📋 More Info
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-orange-50 border-l-4 border-orange-500 rounded-2xl p-6">
                <div className="flex items-start gap-4">
                  <span className="text-3xl">⚠️</span>
                  <div className="flex-1">
                    <h3 className="font-bold text-gray-900 text-lg">Queue Delay Warning</h3>
                    <p className="text-gray-600 text-sm mt-1">Average queue time has increased to 45 minutes. Consider opening additional gates.</p>
                    <div className="mt-3 flex gap-3">
                      <button className="bg-orange-500 hover:bg-orange-600 text-white px-4 py-2 rounded-lg font-semibold text-sm">
                        ✓ Acknowledge
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Reports Tab */}
        {activeTab === 'reports' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-900">📈 Performance Reports</h2>
            <div className="grid md:grid-cols-3 gap-6">
              <button className="bg-white rounded-2xl shadow-lg p-8 hover:shadow-xl transition-all border-l-4 border-blue-500 text-left">
                <p className="text-gray-600 text-sm font-semibold">Today's Summary</p>
                <p className="text-2xl font-bold text-gray-900 mt-2">Generate Report</p>
              </button>
              <button className="bg-white rounded-2xl shadow-lg p-8 hover:shadow-xl transition-all border-l-4 border-green-500 text-left">
                <p className="text-gray-600 text-sm font-semibold">Weekly Performance</p>
                <p className="text-2xl font-bold text-gray-900 mt-2">View Stats</p>
              </button>
              <button className="bg-white rounded-2xl shadow-lg p-8 hover:shadow-xl transition-all border-l-4 border-purple-500 text-left">
                <p className="text-gray-600 text-sm font-semibold">Zone Analytics</p>
                <p className="text-2xl font-bold text-gray-900 mt-2">Detailed Breakdown</p>
              </button>
            </div>

            <div className="bg-white rounded-2xl shadow-lg p-8">
              <h3 className="text-xl font-bold text-gray-900 mb-6">Tasks Completion Rate</h3>
              <div className="h-40 bg-gradient-to-b from-purple-50 to-white rounded-xl p-6 flex items-end justify-around">
                {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day, idx) => (
                  <div key={idx} className="flex flex-col items-center">
                    <div 
                      className="bg-gradient-to-t from-purple-500 to-purple-400 rounded-lg w-10" 
                      style={{height: `${[70, 80, 60, 90, 85, 75, 88][idx]}%`}}
                    ></div>
                    <p className="text-xs text-gray-600 mt-2">{day}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default WorkerDashboard;
